package com.hssa.auth.service.impl; import com.hssa.auth.dto.request.*; import com.hssa.auth.dto.response.AuthenticationResponse; import com.hssa.auth.dto.response.TokenResponse; import com.hssa.auth.dto.response.UserSummaryResponse; import com.hssa.auth.entity.RefreshToken; import com.hssa.auth.entity.Role; import com.hssa.auth.entity.User; import com.hssa.auth.repository.RoleRepository; import com.hssa.auth.repository.UserRepository; import com.hssa.auth.service.AuthService;
import com.hssa.auth.service.JwtService;
import com.hssa.auth.service.RefreshTokenService;
import com.hssa.exception.ResourceNotFoundException;
import com.hssa.security.dto.CustomUserDetails; import jakarta.servlet.http.HttpServletRequest; import org.springframework.security.authentication.AuthenticationManager; import org.springframework.security.authentication.UsernamePasswordAuthenticationToken; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.stereotype.Service; import java.util.HashSet; import java.util.stream.Collectors; @Service public class AuthServiceImpl implements AuthService { private final UserRepository userRepository; private final RoleRepository roleRepository; private final PasswordEncoder passwordEncoder; private final JwtService jwtService; private final AuthenticationManager authenticationManager; private final RefreshTokenService refreshTokenService; public AuthServiceImpl(UserRepository userRepository, RoleRepository roleRepository, PasswordEncoder passwordEncoder, JwtService jwtService, AuthenticationManager authenticationManager, RefreshTokenService refreshTokenService) { this.userRepository = userRepository; this.roleRepository = roleRepository; this.passwordEncoder = passwordEncoder; this.jwtService = jwtService; this.authenticationManager = authenticationManager; this.refreshTokenService = refreshTokenService; } @Override public void register(RegisterRequest request) { if (userRepository.existsByEmail(request.getEmail())) { throw new RuntimeException("Email already exists"); } User user = new User(); user.setFirstName(request.getFirstName()); user.setLastName(request.getLastName()); user.setEmail(request.getEmail()); user.setPasswordHash(passwordEncoder.encode(request.getPassword())); Role userRole = roleRepository.findByRoleCode("USER").orElseThrow(() -> new ResourceNotFoundException("Role USER not found")); user.getRoles().add(userRole); userRepository.save(user); } @Override public AuthenticationResponse login(LoginRequest request, HttpServletRequest httpRequest) { authenticationManager.authenticate(new UsernamePasswordAuthenticationToken(request.getEmail(), request.getPassword())); User user = userRepository.findByEmail(request.getEmail()).orElseThrow(() -> new ResourceNotFoundException("User not found")); CustomUserDetails userDetails = CustomUserDetails.builder().id(user.getId()).email(user.getEmail()).password(user.getPasswordHash()).authorities(new HashSet<>()).build(); String jwtToken = jwtService.generateToken(userDetails); RefreshToken refreshToken = refreshTokenService.createRefreshToken(user.getId()); UserSummaryResponse userSummary = UserSummaryResponse.builder().id(user.getId()).email(user.getEmail()).firstName(user.getFirstName()).lastName(user.getLastName()).displayName(user.getDisplayName()).roles(user.getRoles().stream().map(Role::getRoleCode).collect(Collectors.toSet())).permissions(new HashSet<>()).build(); return AuthenticationResponse.builder().accessToken(jwtToken).refreshToken(refreshToken.getToken()).user(userSummary).build(); } @Override public TokenResponse refreshToken(RefreshTokenRequest request) { return new TokenResponse(); } @Override public void logout(String sessionToken) {} @Override public void forgotPassword(ForgotPasswordRequest request) {} @Override public void resetPassword(ResetPasswordRequest request) {} @Override public void changePassword(ChangePasswordRequest request, String email) {} @Override public void verifyEmail(VerifyEmailRequest request) {} }
